const F={"/404.html": ["text/html; charset=utf-8", ""], "/changelog.html": ["text/html; charset=utf-8", ""], "/download.html": ["text/html; charset=utf-8", ""], "/faq.html": ["text/html; charset=utf-8", ""], "/guide.html": ["text/html; charset=utf-8", ""], "/icon.png": ["image/png", ""], "/index.html": ["text/html; charset=utf-8", ""], "/security.html": ["text/html; charset=utf-8", ""], "/style.css": ["text/css; charset=utf-8", ""]};
const b=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
export default{fetch(r){const u=new URL(r.url);let p=u.pathname;
if(p.endsWith('.html')&&p!=='/404.html'){u.pathname=p==='/index.html'?'/':p.slice(0,-5);return Response.redirect(u.toString(),301)}
if(p.length>1&&p.endsWith('/')){u.pathname=p.slice(0,-1);return Response.redirect(u.toString(),301)}
let f=F[p==='/'?'/index.html':p]||F[p+'.html'];let st=200;
if(!f){f=F['/404.html'];st=404}
return new Response(b(f[1]),{status:st,headers:{'content-type':f[0],'cache-control':'public, max-age=300','x-content-type-options':'nosniff','referrer-policy':'no-referrer'}})}}